                    }
                    results.add(transform.apply(item));
                    consumed++;
                }
            }).start();
        }
    }

    List<String> results() {
        return results;
    }

    long consumedCount() {
        return consumed;
    }

    int highWaterMark() {
        return highWater;
    }
